import React, { useState, useEffect, useRef } from 'react';
import API from '../api/axios';
import io from 'socket.io-client';
import {
  UtensilsCrossed,
  Package,
  History,
  Settings,
  Plus,
  Trash2,
  Phone,
  MessageCircle,
  RefreshCw,
  LogOut,
  CheckCircle,
  Clock,
  X,
  Upload,
  Bell,
  Image as ImageIcon
} from 'lucide-react';

export default function RestaurantApp() {
  const [restaurant, setRestaurant] = useState(() => {
    try {
      const saved = localStorage.getItem('cf_restaurant');
      return saved ? JSON.parse(saved) : null;
    } catch { return null; }
  });

  const [tab, setTab] = useState('orders');
  const [toast, setToast] = useState({ open: false, title: '', message: '' });

  const showToast = (title, message) => {
    setToast({ open: true, title, message });
    setTimeout(() => setToast({ open: false, title: '', message: '' }), 3000);
  };

  const logoutRestaurant = () => {
    localStorage.removeItem('cf_restaurant_token');
    localStorage.removeItem('cf_restaurant');
    setRestaurant(null);
  };

  if (!restaurant) return <RestaurantLogin onLogin={(rest, token) => {
    localStorage.setItem('cf_restaurant_token', token);
    localStorage.setItem('cf_restaurant', JSON.stringify(rest));
    setRestaurant(rest);
    showToast('Login Success', 'Welcome to Restaurant Panel');
  }} showToast={showToast} />;

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 font-sans pb-24 relative">
      {toast.open && (
        <div className="fixed top-4 left-4 right-4 max-w-sm mx-auto z-[9999]">
          <div className="bg-slate-900 text-white px-4 py-3 rounded-2xl shadow-xl flex items-center justify-between border border-emerald-500/40">
            <div>
              <span className="font-bold text-xs text-emerald-400 block">{toast.title}</span>
              <span className="text-[11px] text-gray-200">{toast.message}</span>
            </div>
            <button onClick={() => setToast({ open: false, title: '', message: '' })} className="text-gray-400 hover:text-white">
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>
      )}

      {/* Top Header */}
      <div className="bg-white border-b px-6 py-4 flex justify-between items-center sticky top-0 z-40 shadow-xs">
        <div className="flex items-center gap-3">
          <img src={restaurant.image_url || 'https://via.placeholder.com/150'} alt="Logo" className="w-10 h-10 rounded-xl object-cover border" />
          <div>
            <h1 className="text-sm font-black text-gray-900">{restaurant.name}</h1>
            <span className="text-[10px] text-emerald-600 font-bold uppercase">Restaurant Partner Portal</span>
          </div>
        </div>
        <button onClick={logoutRestaurant} className="px-3 py-1.5 bg-red-50 text-red-600 rounded-xl text-xs font-bold flex items-center gap-1 cursor-pointer">
          <LogOut className="w-3.5 h-3.5" /> Logout
        </button>
      </div>

      <div className="max-w-4xl mx-auto p-4 sm:p-6">
        {tab === 'orders' && <RestaurantOrders restaurantId={restaurant.id} showToast={showToast} />}
        {tab === 'history' && <RestaurantHistory restaurantId={restaurant.id} />}
        {tab === 'products' && <RestaurantProducts restaurantId={restaurant.id} showToast={showToast} />}
        {tab === 'settings' && <RestaurantSettings restaurant={restaurant} setRestaurant={setRestaurant} showToast={showToast} />}
      </div>

      {/* Bottom Nav */}
      <div className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-md border-t py-2.5 px-6 z-50 shadow-lg">
        <div className="max-w-md mx-auto flex justify-between items-center text-xs font-bold">
          {[
            { id: 'orders', label: 'Live Orders', icon: Package },
            { id: 'history', label: 'History & Sales', icon: History },
            { id: 'products', label: 'Products', icon: UtensilsCrossed },
            { id: 'settings', label: 'Settings', icon: Settings }
          ].map((item) => {
            const Icon = item.icon;
            return (
              <button
                key={item.id}
                onClick={() => setTab(item.id)}
                className={`flex flex-col items-center gap-1 cursor-pointer transition-colors ${tab === item.id ? 'text-emerald-600 font-black' : 'text-gray-400 hover:text-gray-600'}`}
              >
                <Icon className="w-5 h-5" />
                <span className="text-[10px]">{item.label}</span>
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
}

// 1. LOGIN COMPONENT
function RestaurantLogin({ onLogin, showToast }) {
  const [restaurants, setRestaurants] = useState([]);
  const [selectedRestId, setSelectedRestId] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    API.get('/restaurants').then((res) => {
      setRestaurants(Array.isArray(res.data) ? res.data : []);
    });
  }, []);

  const handleLoginSubmit = async (e) => {
    e.preventDefault();
    if (!selectedRestId) {
      showToast('Error', 'Please select a restaurant!');
      return;
    }
    setLoading(true);
    try {
      const res = await API.post('/restaurant/login', {
        restaurant_id: selectedRestId,
        password: password.trim()
      });
      if (res.data.success) {
        onLogin(res.data.restaurant, res.data.token);
      }
    } catch (err) {
      showToast('Login Failed', err.response?.data?.error || 'Incorrect password!');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center p-4 font-sans">
      <div className="bg-white rounded-3xl p-8 max-w-md w-full shadow-2xl space-y-5">
        <div className="text-center space-y-1">
          <div className="w-14 h-14 bg-emerald-600 text-white rounded-2xl flex items-center justify-center mx-auto text-xl font-black">
            🍔
          </div>
          <h2 className="text-2xl font-black text-gray-900">Restaurant Partner</h2>
          <p className="text-xs text-gray-500 font-semibold">Select your restaurant and enter password</p>
        </div>

        <form onSubmit={handleLoginSubmit} className="space-y-4 text-xs font-bold">
          <div>
            <label className="text-gray-600 uppercase">Select Restaurant</label>
            <select
              value={selectedRestId}
              onChange={(e) => setSelectedRestId(e.target.value)}
              className="w-full px-3.5 py-3 border rounded-xl mt-1 bg-white font-semibold outline-none"
              required
            >
              <option value="">-- Choose Restaurant --</option>
              {restaurants.map((r) => (
                <option key={r.id} value={r.id}>{r.name} ({r.phone})</option>
              ))}
            </select>
          </div>

          <div>
            <label className="text-gray-600 uppercase">Password</label>
            <input
              type="password"
              required
              placeholder="••••••••"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full px-3.5 py-3 border rounded-xl mt-1 font-semibold outline-none"
            />
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full py-3 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl font-black text-sm shadow-md cursor-pointer"
          >
            {loading ? 'Logging in...' : 'Login to Panel'}
          </button>
        </form>
      </div>
    </div>
  );
}

// 2. LIVE ORDERS PAGE
function RestaurantOrders({ restaurantId, showToast }) {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [newOrderPopup, setNewOrderPopup] = useState(null);
  const audioRef = useRef(null);

  const fetchOrders = async () => {
    try {
      setLoading(true);
      const res = await API.get(`/restaurant/${restaurantId}/orders`);
      setOrders(Array.isArray(res.data) ? res.data : []);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchOrders();

    const socket = io('http://localhost:5000');
    socket.on('new_order', (orderData) => {
      let itemsArr = [];
      try { itemsArr = typeof orderData.items === 'string' ? JSON.parse(orderData.items) : (orderData.items || []); } catch { itemsArr = []; }

      const isForMe = Number(orderData.restaurant_id) === Number(restaurantId) || itemsArr.some(it => Number(it.restaurant_id) === Number(restaurantId));

      if (isForMe) {
        setNewOrderPopup(orderData);
        fetchOrders();
      }
    });

    return () => {
      socket.disconnect();
    };
  }, [restaurantId]);

  useEffect(() => {
    const hasPending = orders.some(o => String(o.status).toLowerCase() === 'pending');
    if (hasPending || newOrderPopup) {
      if (!audioRef.current) {
        audioRef.current = new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3');
        audioRef.current.loop = true;
      }
      audioRef.current.play().catch(e => console.log('Audio autoplay prevented:', e));
    } else {
      if (audioRef.current) {
        audioRef.current.pause();
        audioRef.current.currentTime = 0;
      }
    }
  }, [orders, newOrderPopup]);

  const updateStatus = async (orderId, newStatus) => {
    try {
      await API.patch(`/restaurant/orders/${orderId}/status`, { status: newStatus });
      showToast('Status Updated', `Order marked as ${newStatus}`);
      setNewOrderPopup(null);
      fetchOrders();
    } catch (err) {
      showToast('Error', 'Failed to update order status');
    }
  };

  return (
    <div className="space-y-4 relative">
      {newOrderPopup && (
        <div className="fixed inset-0 bg-slate-950/70 backdrop-blur-sm z-[9999] flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-6 max-w-sm w-full shadow-2xl space-y-4 text-center">
            <div className="w-16 h-16 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto">
              <Bell className="w-8 h-8 animate-ping" />
            </div>
            <div>
              <h3 className="text-xl font-black text-gray-900">🚨 New Order Received!</h3>
              <p className="text-xs text-gray-500 mt-1">Order #ORD-{newOrderPopup.id} requires your action.</p>
            </div>
            <div className="bg-gray-50 p-3 rounded-2xl text-left text-xs space-y-1 font-semibold">
              <p>Customer: {newOrderPopup.customer_name}</p>
              <p className="text-emerald-700 font-black">Amount: ৳{newOrderPopup.total_amount}</p>
            </div>
            <div className="flex gap-2 pt-2">
              <button
                onClick={() => updateStatus(newOrderPopup.id, 'cancelled')}
                className="flex-1 py-2.5 bg-red-50 text-red-600 rounded-xl font-bold text-xs hover:bg-red-100 cursor-pointer"
              >
                Cancel
              </button>
              <button
                onClick={() => updateStatus(newOrderPopup.id, 'accepted')}
                className="flex-1 py-2.5 bg-emerald-600 text-white rounded-xl font-bold text-xs hover:bg-emerald-700 cursor-pointer shadow-md"
              >
                Accept Order
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="flex justify-between items-center">
        <h2 className="text-lg font-black text-gray-900">Ongoing Orders ({orders.length})</h2>
        <button onClick={fetchOrders} className="p-2 border rounded-xl bg-white shadow-xs cursor-pointer">
          <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin text-emerald-600' : ''}`} />
        </button>
      </div>

      {loading && orders.length === 0 ? (
        <div className="p-12 text-center text-gray-400 font-bold">Loading orders...</div>
      ) : orders.length === 0 ? (
        <div className="bg-white p-12 text-center rounded-3xl border text-gray-400 font-bold">No ongoing orders right now.</div>
      ) : (
        <div className="space-y-4">
          {orders.map((order) => {
            let itemsArr = [];
            try { itemsArr = typeof order.items === 'string' ? JSON.parse(order.items) : (order.items || []); } catch { itemsArr = []; }
            const isPending = String(order.status).toLowerCase() === 'pending';

            return (
              <div key={order.id} className={`bg-white rounded-3xl p-5 border shadow-sm space-y-3 ${isPending ? 'border-amber-400 ring-2 ring-amber-100' : ''}`}>
                <div className="flex justify-between items-start border-b pb-3">
                  <div>
                    <span className="text-sm font-black text-gray-900">#ORD-{order.id}</span>
                    <span className="text-xs text-gray-400 block">{new Date(order.created_at).toLocaleString()}</span>
                  </div>
                  <span className={`px-3 py-1 rounded-xl text-xs font-black uppercase ${isPending ? 'bg-amber-500 text-white animate-pulse' : 'bg-blue-100 text-blue-800'}`}>
                    {order.status}
                  </span>
                </div>

                {order.note && (
                  <div className="p-3 bg-red-50 border border-red-200 rounded-2xl text-xs font-bold text-red-600 space-y-0.5 shadow-xs">
                    <span className="uppercase text-[10px] tracking-wider block">⚠️ Customer Note:</span>
                    <p className="font-black text-red-700 text-sm">{order.note}</p>
                  </div>
                )}

                <div className="bg-gray-50 p-3 rounded-2xl text-xs space-y-1">
                  <p className="font-bold text-gray-900">Customer: {order.customer_name} ({order.customer_phone})</p>
                  <p className="text-gray-600">Address: {order.address}</p>
                  <div className="flex gap-2 pt-2">
                    <a href={`tel:${order.customer_phone}`} className="px-3 py-1.5 bg-emerald-600 text-white rounded-xl font-bold flex items-center gap-1 shadow-xs">
                      <Phone className="w-3.5 h-3.5" /> Call
                    </a>
                    <a href={`https://wa.me/88${order.customer_phone}`} target="_blank" rel="noreferrer" className="px-3 py-1.5 bg-emerald-500 text-white rounded-xl font-bold flex items-center gap-1 shadow-xs">
                      <MessageCircle className="w-3.5 h-3.5" /> WhatsApp
                    </a>
                  </div>
                </div>

                <div className="space-y-1 text-xs">
                  <span className="font-black text-gray-400 uppercase text-[10px]">Ordered Items:</span>
                  {itemsArr.map((it, idx) => (
                    <div key={idx} className="flex justify-between font-semibold text-gray-800">
                      <span>{it.qty}x {it.name}</span>
                      <span>৳{it.price * it.qty}</span>
                    </div>
                  ))}
                </div>

                <div className="flex justify-between items-center pt-3 border-t">
                  <span className="font-black text-sm text-emerald-700">Total: ৳{order.total_amount}</span>
                  <div className="flex gap-2">
                    <button
                      onClick={() => updateStatus(order.id, 'cancelled')}
                      className="px-4 py-2 bg-red-50 hover:bg-red-100 text-red-600 rounded-xl font-bold text-xs cursor-pointer shadow-xs"
                    >
                      Cancel
                    </button>
                    {isPending && (
                      <button
                        onClick={() => updateStatus(order.id, 'accepted')}
                        className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold text-xs cursor-pointer shadow-xs"
                      >
                        Accept
                      </button>
                    )}
                    <button
                      onClick={() => updateStatus(order.id, 'ready')}
                      className="px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl font-bold text-xs cursor-pointer shadow-xs"
                    >
                      Ready
                    </button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

// 3. HISTORY & SALES PAGE
function RestaurantHistory({ restaurantId }) {
  const [history, setHistory] = useState([]);
  const [dateFilter, setDateFilter] = useState('all');
  const [customDate, setCustomDate] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');

  useEffect(() => {
    API.get(`/restaurant/${restaurantId}/history?dateFilter=${dateFilter}&customDate=${customDate}&statusFilter=${statusFilter}`).then((res) => {
      setHistory(Array.isArray(res.data) ? res.data : []);
    });
  }, [dateFilter, customDate, statusFilter, restaurantId]);

  const deliveredOrders = history.filter(h => String(h.status).toLowerCase() === 'delivered');
  const totalSalesExcludingDelivery = deliveredOrders.reduce((sum, h) => {
    let itemsArr = [];
    try { itemsArr = typeof h.items === 'string' ? JSON.parse(h.items) : (h.items || []); } catch { itemsArr = []; }
    let restFoodTotal = 0;
    itemsArr.forEach(it => {
      if (Number(it.restaurant_id) === Number(restaurantId)) {
        restFoodTotal += Number(it.price || 0) * Number(it.qty || 1);
      }
    });
    if (restFoodTotal === 0 && Number(h.restaurant_id) === Number(restaurantId)) {
      restFoodTotal = Number(h.total_amount || 0) - Number(h.delivery_fee || 0);
    }
    return sum + restFoodTotal;
  }, 0);

  return (
    <div className="space-y-4">
      <h2 className="text-lg font-black text-gray-900">Order History & Sales</h2>

      <div className="bg-gradient-to-r from-emerald-600 to-teal-700 p-5 rounded-3xl text-white shadow-md space-y-1">
        <span className="text-xs font-bold uppercase tracking-wider text-emerald-100">Total Sales (Excluding Delivery Fee)</span>
        <h3 className="text-3xl font-black">৳ {totalSalesExcludingDelivery.toLocaleString()}</h3>
        <p className="text-xs text-emerald-200">Based on delivered orders ({deliveredOrders.length} orders)</p>
      </div>

      <div className="flex flex-wrap gap-2 text-xs font-bold items-center bg-white p-3 rounded-2xl border">
        <span className="text-gray-400">Date:</span>
        {['all', 'today', 'yesterday', 'last7days', 'custom'].map((f) => (
          <button
            key={f}
            onClick={() => setDateFilter(f)}
            className={`px-3 py-1.5 rounded-xl border uppercase cursor-pointer ${dateFilter === f ? 'bg-slate-900 text-white' : 'bg-gray-50 text-gray-700'}`}
          >
            {f}
          </button>
        ))}
        {dateFilter === 'custom' && (
          <input
            type="date"
            value={customDate}
            onChange={(e) => setCustomDate(e.target.value)}
            className="px-2 py-1 border rounded-xl text-xs font-bold"
          />
        )}
      </div>

      <div className="flex gap-2 text-xs font-bold">
        <span className="text-gray-400 self-center">Status:</span>
        {['all', 'delivered', 'cancelled'].map((st) => (
          <button
            key={st}
            onClick={() => setStatusFilter(st)}
            className={`px-3 py-1.5 rounded-xl border uppercase cursor-pointer ${statusFilter === st ? 'bg-emerald-600 text-white' : 'bg-white text-gray-700'}`}
          >
            {st}
          </button>
        ))}
      </div>

      <div className="space-y-3">
        {history.map((item) => (
          <div key={item.id} className="bg-white rounded-3xl p-4 border shadow-sm space-y-2 text-xs">
            <div className="flex justify-between font-bold">
              <span className="text-sm font-black text-gray-900">#ORD-{item.id}</span>
              <span className={`uppercase font-black px-2 py-0.5 rounded ${item.status === 'delivered' ? 'bg-emerald-100 text-emerald-800' : 'bg-red-100 text-red-700'}`}>
                {item.status}
              </span>
            </div>
            <p className="text-gray-500">Customer: {item.customer_name} ({item.customer_phone})</p>
            <div className="flex justify-between pt-2 border-t font-black">
              <span>Payment: {item.payment_method}</span>
              <span className="text-emerald-700 text-sm">Total: ৳{item.total_amount}</span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

// 4. PRODUCTS MANAGEMENT PAGE (With File Image Upload & Number Priority 1,2,3...)
function RestaurantProducts({ restaurantId, showToast }) {
  const [products, setProducts] = useState([]);
  const [name, setName] = useState('');
  const [price, setPrice] = useState('');
  const [category, setCategory] = useState('');
  const [imageFile, setImageFile] = useState(null);
  const [priority, setPriority] = useState('1');
  const [loading, setLoading] = useState(false);

  const fetchProducts = async () => {
    try {
      const res = await API.get(`/restaurant/${restaurantId}/products`);
      setProducts(Array.isArray(res.data) ? res.data : []);
    } catch (err) {
      console.error(err);
    }
  };

  useEffect(() => {
    fetchProducts();
  }, [restaurantId]);

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImageFile(reader.result); // Base64 format
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAddProduct = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      await API.post('/restaurant/products', {
        restaurant_id: restaurantId,
        name,
        price: Number(price),
        category: category || 'General',
        image_url: imageFile || '',
        priority: Number(priority) || 1
      });
      showToast('Success', 'Product added successfully!');
      setName('');
      setPrice('');
      setCategory('');
      setImageFile(null);
      setPriority('1');
      fetchProducts();
    } catch (err) {
      showToast('Error', 'Failed to add product');
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteProduct = async (prodId) => {
    if (!window.confirm('Are you sure to delete this product?')) return;
    try {
      await API.delete(`/restaurant/products/${prodId}`);
      showToast('Deleted', 'Product removed successfully!');
      fetchProducts();
    } catch (err) {
      showToast('Error', 'Failed to delete product');
    }
  };

  return (
    <div className="space-y-6">
      <h2 className="text-lg font-black text-gray-900">Manage Menu Products</h2>

      <form onSubmit={handleAddProduct} className="bg-white rounded-3xl p-5 border shadow-sm space-y-3 text-xs font-bold">
        <h3 className="text-sm font-black text-gray-800">Add New Product</h3>
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          <div>
            <label className="text-gray-600 uppercase">Product Name</label>
            <input type="text" required value={name} onChange={e => setName(e.target.value)} placeholder="Burger, Pizza..." className="w-full px-3 py-2 border rounded-xl mt-1 font-semibold" />
          </div>
          <div>
            <label className="text-gray-600 uppercase">Price (৳)</label>
            <input type="number" required value={price} onChange={e => setPrice(e.target.value)} placeholder="250" className="w-full px-3 py-2 border rounded-xl mt-1 font-semibold" />
          </div>
          <div>
            <label className="text-gray-600 uppercase">Category</label>
            <input type="text" value={category} onChange={e => setCategory(e.target.value)} placeholder="Fast Food, Drinks..." className="w-full px-3 py-2 border rounded-xl mt-1 font-semibold" />
          </div>
          <div>
            <label className="text-gray-600 uppercase">Product Image (File Upload)</label>
            <input type="file" accept="image/*" onChange={handleImageChange} className="w-full px-3 py-1.5 border rounded-xl mt-1 font-semibold bg-gray-50 cursor-pointer" />
          </div>
          <div>
            <label className="text-gray-600 uppercase">Priority (1, 2, 3, 4...)</label>
            <input type="number" min="1" value={priority} onChange={e => setPriority(e.target.value)} placeholder="1" className="w-full px-3 py-2 border rounded-xl mt-1 font-semibold" />
          </div>
        </div>
        <button type="submit" disabled={loading} className="w-full py-3 bg-emerald-600 text-white rounded-xl font-black cursor-pointer shadow-md mt-2">
          {loading ? 'Adding...' : 'Add Product'}
        </button>
      </form>

      <div className="space-y-3">
        <h3 className="text-sm font-black text-gray-800">Existing Products ({products.length})</h3>
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          {products.map(p => (
            <div key={p.id} className="bg-white p-3 rounded-2xl border shadow-xs flex items-center justify-between">
              <div className="flex items-center gap-3">
                <img src={p.image_url || 'https://via.placeholder.com/80'} alt="" className="w-12 h-12 rounded-xl object-cover border" />
                <div>
                  <h4 className="font-bold text-gray-900 text-xs">{p.name}</h4>
                  <span className="text-[10px] text-gray-400 block">{p.category} • Priority: {p.priority}</span>
                  <span className="font-black text-emerald-600 text-xs">৳{p.price}</span>
                </div>
              </div>
              <button onClick={() => handleDeleteProduct(p.id)} className="p-2 bg-red-50 text-red-600 rounded-xl cursor-pointer hover:bg-red-100">
                <Trash2 className="w-4 h-4" />
              </button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

// 5. SETTINGS PAGE (With File Image Upload for Logo)
function RestaurantSettings({ restaurant, setRestaurant, showToast }) {
  const [logoFile, setLogoFile] = useState(restaurant.image_url || '');
  const [loading, setLoading] = useState(false);

  const handleLogoFileChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setLogoFile(reader.result); // Base64 format
      };
      reader.readAsDataURL(file);
    }
  };

  const handleUpdateLogo = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      const res = await API.put(`/restaurant/${restaurant.id}/logo`, { image_url: logoFile });
      if (res.data.success) {
        setRestaurant(res.data.restaurant);
        localStorage.setItem('cf_restaurant', JSON.stringify(res.data.restaurant));
        showToast('Success', 'Restaurant logo updated successfully!');
      }
    } catch (err) {
      showToast('Error', 'Failed to update logo');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-4 max-w-lg mx-auto bg-white p-6 rounded-3xl border shadow-sm font-sans">
      <h2 className="text-lg font-black text-gray-900">Restaurant Settings</h2>

      <form onSubmit={handleUpdateLogo} className="space-y-4 text-xs font-bold">
        <div className="text-center space-y-2">
          <img src={logoFile || 'https://via.placeholder.com/150'} alt="Logo Preview" className="w-24 h-24 mx-auto rounded-2xl object-cover border shadow-sm" />
          <p className="text-[11px] text-gray-400">Current Restaurant Logo</p>
        </div>

        <div>
          <label className="text-gray-600 uppercase">Upload New Restaurant Logo (Image File)</label>
          <input
            type="file"
            accept="image/*"
            onChange={handleLogoFileChange}
            className="w-full px-3 py-2.5 border rounded-xl mt-1 font-semibold bg-gray-50 cursor-pointer"
          />
        </div>

        <button
          type="submit"
          disabled={loading}
          className="w-full py-3 bg-emerald-600 text-white rounded-xl font-black shadow-md cursor-pointer flex items-center justify-center gap-2"
        >
          <Upload className="w-4 h-4" /> {loading ? 'Updating...' : 'Update Logo'}
        </button>
      </form>
    </div>
  );
}
